116	public enum OrderStatus {
117	    PENDING_PAYMENT, // 결제 대기
118	    PAYMENT_COMPLETED, // 결제 완료
119	    PREPARING, // 상품 준비 중
120	    IN_WAREHOUSE, // 창고 보관 중
121	    SHIPMENT_STARTED, // 배송 시작
122	    IN_TRANSIT, // 배송 중
123	    COMPLETED, // 배송 완료
124	    REFUND_REQUESTED, // 환불 대기
125	    REFUNDED; // 환불 완료
126	
127	    // 각 상태에서 전이 가능한 다음 상태들을 정의
128	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
129	
130	    static {
131	        // 상태 전이 규칙 초기화
132	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
133	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
134	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
135	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
136	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
137	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
138	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
139	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
140	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
141	    }
142	
143	    /**
144	     * 현재 상태에서 새 상태로 전이가 가능한지 확인합니다.
145	     *
146	     * @param newStatus 전이하려는 새 상태
147	     * @return 전이 가능 여부
148	     */
149	    public boolean canTransitionTo(OrderStatus newStatus) {
150	        Set<OrderStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
151	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
152	    }
153	
154	    /**
155	     * 현재 상태에서 전이 가능한 모든 상태를 반환합니다.
156	     *
157	     * @return 전이 가능한 상태 집합
158	     */
159	    public Set<OrderStatus> getAllowedNextStates() {
160	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
161	    }
